package vn.edu.hcmute.bookstore_24110202.controller; import jakarta.servlet.annotation.*; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.*; import vn.edu.hcmute.bookstore_24110202.dto.*; import vn.edu.hcmute.bookstore_24110202.service.impl.*;
@WebServlet("/verify-otp") public class VerifyOtpController_24110202 extends HttpServlet {private final UserServiceImpl_24110202 users=new UserServiceImpl_24110202();protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{q.getRequestDispatcher("/WEB-INF/views/auth/verify-otp.jsp").include(q,p);}protected void doPost(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("pendingRegisterForm")==null){p.sendRedirect(q.getContextPath()+"/register");return;}int attempts=(Integer)s.getAttribute("otpAttempts");String input=q.getParameter("otp"),actual=(String)s.getAttribute("registerOtp");if(System.currentTimeMillis()>(Long)s.getAttribute("otpExpiresAt")||attempts>=5){s.removeAttribute("pendingRegisterForm");q.setAttribute("message","Mã OTP đã hết hạn hoặc vượt quá số lần thử.");doGet(q,p);return;}if(!java.util.Objects.equals(input,actual)){s.setAttribute("otpAttempts",attempts+1);q.setAttribute("message","Mã OTP không đúng.");doGet(q,p);return;}users.register((RegisterForm_24110202)s.getAttribute("pendingRegisterForm"));s.removeAttribute("pendingRegisterForm");s.removeAttribute("registerOtp");s.removeAttribute("otpExpiresAt");s.removeAttribute("otpAttempts");s.setAttribute("flashSuccess","Đăng ký thành công, hãy đăng nhập.");p.sendRedirect(q.getContextPath()+"/login");}}
